import {WAVE_NEW_TYPES} from './encounters.mjs';
import {ENEMY_TYPES} from './catalog.mjs';
import {ACCESSORIES,MUZZLES,offerAccessories} from './equipment.mjs';
import {visibleInCombat,ARENA_BOUNDS} from './view.mjs';
export const WAVE_SECONDS=[30,40,50,60,70,80,90,100,110,120];
export const waveKind=w=>[3,5,7].includes(w)?'elite':w===9?'boss':w===10?'final':'normal';
export function beginReward(r,kind){if(r.rewardTaken)return;r.rewardTaken=true;r.rewardKind=kind;r.rewardChoices=kind==='accessory'?offerAccessories(r.lab.gun.type,r.attachments,r.random):Object.keys(MUZZLES).sort(()=>r.random()-.5).slice(0,3);r.state='reward';r.events.push('reward')}
export function chooseReward(r,id,slot=null){if(r.state!=='reward')return false;if(id===null){r.state='playing';r.rewardChoices=[];return true}if(!r.rewardChoices.includes(id))return false;if(r.rewardKind==='accessory'){if(r.attachments.includes(id))return false;if(r.attachments.length>=2){if(!Number.isInteger(slot)||slot<0||slot>1)return false;r.attachments[slot]=id}else r.attachments.push(id);r.accessoryCharge={};r.condenser.clear()}else r.muzzle=id;r.rewardChoices=[];r.state='playing';return true}
export const ELITE_WAVES=[3,5,7];
export function spawnElite(r,introWave,x,y,special=false){const type=WAVE_NEW_TYPES[introWave-1],def=ENEMY_TYPES[type];return r.spawnEnemy(type,x,y,{elite:true,special,eliteIntro:introWave,hp:def.hp*6,maxHp:def.hp*6,speed:(def.speed+(r.wave-1)*4)*1.45,damage:def.damage*1.6,attackRate:1.65,r:def.r*1.3})}
export function tryRecurringElite(r,x,y){const eligible=(r.eliteIntroduced||[]).filter(w=>w<=r.wave&&!r.enemies.some(e=>e.hp>0&&e.special&&e.eliteIntro===w));const cap=(r.wave>=8?3:2)-(ELITE_WAVES.includes(r.wave)&&!r.specialSpawned?1:0);if(!eligible.length||r.enemies.filter(e=>e.hp>0&&e.elite).length>=cap||r.random()>=.18)return null;return spawnElite(r,eligible[Math.floor(r.random()*eligible.length)],x,y,false)}
export function specialSpawn(r){const kind=waveKind(r.wave);if(kind==='normal'||r.specialSpawned)return;const at=kind==='elite'?12:5;if(r.waveTime<at)return;r.specialSpawned=true;let e;if(kind==='elite'){e=spawnElite(r,r.wave,600,130,true);if(e&&!r.eliteIntroduced.includes(r.wave))r.eliteIntroduced.push(r.wave)}else{const final=kind==='final',type=final?6:4,def=ENEMY_TYPES[type],hp=final?2400:1500;e=r.spawnEnemy(type,600,130,{special:true,hp,maxHp:hp,speed:def.speed,damage:def.damage,r:def.r})}if(e){r.specialId=e.id;r.events.push(kind==='elite'?'elite':'boss')}}
export function updateRanged(r,dt,bounds){for(const e of r.enemies){if(e.hp<=0||e.type!==5)continue;e.rangedTimer=(e.rangedTimer??1.7)-dt;const dx=r.x-e.x,dy=r.y-e.y,d=Math.hypot(dx,dy)||1;if(d<270){e.x=Math.max(ARENA_BOUNDS.left+e.r,Math.min(ARENA_BOUNDS.right-e.r,e.x-dx/d*e.speed*dt));e.y=Math.max(ARENA_BOUNDS.top+e.r,Math.min(ARENA_BOUNDS.bottom-e.r,e.y-dy/d*e.speed*dt))}if(!visibleInCombat(e,bounds)){e.rangedTimer=Math.max(.8,e.rangedTimer);e.aimWarning=undefined;continue}if(e.rangedTimer<=.8&&e.aimWarning===undefined){e.aimAngle=Math.atan2(r.y-e.y,r.x-e.x);e.aimWarning=.8}if(e.aimWarning>0)e.aimWarning=Math.max(0,e.aimWarning-dt);if(e.rangedTimer<=0){const a=e.aimAngle??Math.atan2(dy,dx);r.enemyBullets.push({x:e.x,y:e.y,vx:Math.cos(a)*190,vy:Math.sin(a)*190,damage:e.damage,metal:true,life:5});e.rangedTimer=2.5/(e.attackRate||1);e.aimWarning=undefined}}
 for(const b of r.enemyBullets){const ox=b.x,oy=b.y;if(b.metal&&r.magneticTime>0&&Math.hypot(b.x-r.x,b.y-r.y)<110){const a=Math.atan2(b.y-r.y,b.x-r.x);b.vx=Math.cos(a)*260;b.vy=Math.sin(a)*260;b.deflected=true;r.burst(b.x,b.y,'#ddbeff',3)}b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;const dx=b.x-ox,dy=b.y-oy,u=Math.max(0,Math.min(1,((r.x-ox)*dx+(r.y-oy)*dy)/(dx*dx+dy*dy||1)));if(!b.deflected&&Math.hypot(r.x-ox-u*dx,r.y-oy-u*dy)<21){r.hurt(b.damage);b.life=0}}
 r.enemyBullets=r.enemyBullets.filter(b=>b.life>0&&b.x>=bounds.left&&b.x<=bounds.right&&b.y>=bounds.top&&b.y<=bounds.bottom).slice(-180);
}
